descriptor.templateCss:
.msl {
    --msl-c: #94a3b8;
    --msl-orb-ink: #ffffff;
    /* the family palette, resolved from the real backdrop below */
    --msl-ink: rgba(0, 0, 0, .85);
    /* #78849a is the family muted grey; one step darker here because in this widget it
    only ever carries 10-12px uppercase text, which WCAG counts as normal, not large */
    --msl-muted: #697585;
    --msl-line: #e2e7ef;
    /* the controller overrides this inline with the size that actually fits */
    --msl-orb-size: 54px;
    --msl-gap: 8px;
    --msl-tile-pad: 8px 7px;
    --msl-tile-min: 68px;
    --msl-text-gap: 6px;
    --msl-name-size: 12.5px;
    width: 100%;
    height: 100%;
    box-sizing: border-box;
    padding: 10px 12px;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    color: var(--msl-ink);
    font-family: inherit;
    font-variant-numeric: tabular-nums;
}
.msl--sm {
    --msl-gap: 6px;
    --msl-tile-pad: 5px 5px;
    --msl-tile-min: 52px;
    --msl-text-gap: 4px;
    --msl-name-size: 11.5px;
    --msl-label-size: 11px;
    --msl-key-size: 9.5px;
    padding: 7px 8px;
}
.msl--lg {
    --msl-gap: 10px;
    --msl-tile-pad: 11px 9px;
    --msl-tile-min: 84px;
    --msl-name-size: 14px;
    --msl-label-size: 15px;
    --msl-key-size: 11px;
}
/* Once both captions are gone the tile is only a lamp, so the text-sized floor has to go
with them - otherwise the smallest step still reserves room for words that are not being
drawn, and a 156x100 card wrapped to three rows and scrolled. */
.msl--bare { --msl-tile-min: 0px; }

/* ---- head: entity name left, verdict chip right ---- */
.msl__head {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 8px;
    flex: none;
}
.msl__name {
    flex: 1 1 auto;
    min-width: 0;
    font-size: var(--msl-name-size);
    font-family: var(--msl-name-family, inherit);
    font-weight: var(--msl-name-weight, 600);
    font-style: var(--msl-name-style, normal);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.msl__chip {
    flex: none;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: .05em;
    text-transform: uppercase;
    padding: 2px 7px;
    border-radius: 9px;
    max-width: 50%;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ---- strip ---- */
.msl__strip {
    flex: 1 1 auto;
    min-height: 0;
    display: flex;
    flex-wrap: wrap;
    align-content: center;
    gap: var(--msl-gap);
    overflow: auto;
}
.msl__tile {
    position: relative;
    flex: 1 1 var(--msl-tile-min);
    min-width: var(--msl-tile-min);
    max-width: calc(var(--msl-orb-size) * 2.6 + 40px);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--msl-text-gap);
    padding: var(--msl-tile-pad);
    box-sizing: border-box;
    border: 1px solid var(--msl-line);
    /* the state colour is the only colour on the tile - a hairline under the lamp, the
    way the family tints its border rather than its fill */
    border-bottom: 2px solid var(--msl-c);
    border-radius: 6px;
}
.msl__tile--stale { opacity: .55; filter: saturate(.35); }

/* ---- lamp ---- */
.msl__orb-wrap {
    position: relative;
    width: var(--msl-orb-size);
    height: var(--msl-orb-size);
    display: flex;
    align-items: center;
    justify-content: center;
    flex: none;
}
.msl__halo {
    position: absolute;
    inset: -18%;
    border-radius: 50%;
    background: radial-gradient(circle,
        color-mix(in srgb, var(--msl-c) 34%, transparent),
        color-mix(in srgb, var(--msl-c) 0%, transparent) 70%);
    animation: msl-breathe 3.4s ease-in-out infinite;
}
.msl__orb {
    position: relative;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    /* flat fill, not a radial gradient with a specular highlight: the family is flat, and
    the lamp reads as a lamp from its shape, its glow and its glyph */
    background: var(--msl-c);
}
.msl__orb--square { border-radius: 25%; }
.msl__icon {
    color: var(--msl-orb-ink);
    width: calc(var(--msl-orb-size) * .52);
    height: calc(var(--msl-orb-size) * .52);
    font-size: calc(var(--msl-orb-size) * .52);
    line-height: calc(var(--msl-orb-size) * .52);
}

/* ---- text ---- */
.msl__key {
    max-width: 100%;
    font-size: var(--msl-key-size, 10px);
    font-family: var(--msl-key-family, inherit);
    font-weight: var(--msl-key-weight, 700);
    font-style: var(--msl-key-style, normal);
    letter-spacing: .04em;
    text-transform: uppercase;
    color: var(--msl-muted);
    text-align: center;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.msl__label {
    max-width: 100%;
    font-size: var(--msl-label-size, 13px);
    font-family: var(--msl-label-family, inherit);
    font-weight: var(--msl-label-weight, 700);
    font-style: var(--msl-label-style, normal);
    letter-spacing: -.01em;
    line-height: 1.15;
    text-align: center;
    color: var(--msl-ink);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ---- foot ---- */
.msl__foot {
    flex: none;
    margin-top: auto;
    padding-top: 6px;
    border-top: 1px solid var(--msl-line);
    display: flex;
    align-items: baseline;
    gap: 8px;
    font-size: 10.5px;
    color: var(--msl-muted);
    white-space: nowrap;
    overflow: hidden;
}
.msl__foot-item {
    /* whole or dropped - fitFoot decides which; the age is the only item that yields */
    flex: 0 0 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}
.msl__foot-item + .msl__foot-item::before {
    content: '\00b7';
    margin-right: 8px;
    opacity: .6;
}
.msl__foot-fresh {
    /* gives way first: an age stamp reading "13s" instead
    of "13s ago" costs the operator nothing, a truncated channel count costs them a fact */
    margin-left: auto;
    flex: 0 100 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ---- loading / empty / error ---- */
.msl__skeleton {
    flex: 1;
    display: flex;
    gap: 10px;
    align-items: center;
    justify-content: center;
}
.msl__skel {
    width: var(--msl-orb-size);
    height: var(--msl-orb-size);
    border-radius: 50%;
    background: color-mix(in srgb, var(--msl-muted) 22%, transparent);
    animation: msl-breathe 1.4s ease-in-out infinite;
}
.msl__screen {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 7px;
    text-align: center;
    padding: 10px;
}
.msl__screen-icon {
    color: var(--msl-muted);
    opacity: .8;
}
.msl__screen-icon--bad { color: #ef4444; }
.msl__screen-title { font-size: 12px; font-weight: 600; }
.msl__screen-hint { font-size: 10.5px; color: var(--msl-muted); line-height: 1.35; }

/* ---- motion ---- */
@keyframes msl-breathe {
    0%, 100% { opacity: .85; }
    50% { opacity: .45; }
}
@keyframes msl-pulse {
    0%, 100% { transform: scale(1); opacity: .9; }
    50% { transform: scale(1.18); opacity: .35; }
}
@keyframes msl-orbblink {
    0%, 100% { opacity: 1; }
    50% { opacity: .38; }
}
.msl__tile--blink .msl__halo { animation: msl-pulse 1.15s ease-in-out infinite; }
.msl__tile--blink .msl__orb { animation: msl-orbblink 1.1s ease-in-out infinite; }

@media (prefers-reduced-motion: reduce) {
    .msl__halo, .msl__skel { animation: none !important; }
    .msl__tile--blink .msl__orb { animation: none !important; }
}

descriptor.controllerScript:
self.typeParameters = function() {
    return {
        // Measured on the engine at the shipped 8x4 card: 12 lamps still render with the key
        // name AND the state caption (lamp 59 px); 16 lamps drop both (--bare, lamp 23 px).
        // So 12 is the last size at which a strip of one key per device is still a labelled
        // board. maxDataKeys stays 10 - ten keys on one device already measured good, and
        // lowering it would take capability away from the single-entity card.
        maxDatasources: 12,
        maxDataKeys: 10,
        singleEntity: false,
        previewWidth: '400px',
        previewHeight: '200px',
        embedTitlePanel: true
    };
};

// The built-in led indicator makes the operator write parseValueFunction to turn a
// value into a boolean. These two sets do that job as a setting instead: they are only
// consulted after an exact string and a numeric compare have both missed, so an enum
// that really does use "0" and "1" still matches literally and is never aliased.
var TRUE_WORDS = ['true', 'on', '1', 'yes', 'active', 'open', 'run', 'running'];
var FALSE_WORDS = ['false', 'off', '0', 'no', 'inactive', 'closed', 'idle', 'stop', 'stopped'];

self.num = function(v) {
    if (typeof v === 'number') { return isFinite(v) ? v : null; }
    if (typeof v === 'string' && v.trim() !== '' && !isNaN(+v)) { return +v; }
    return null;
};

self.canonBool = function(v) {
    if (typeof v === 'boolean') { return v; }
    if (typeof v === 'number') { return v === 1 ? true : (v === 0 ? false : null); }
    if (typeof v === 'string') {
        var s = v.trim().toLowerCase();
        if (TRUE_WORDS.indexOf(s) > -1) { return true; }
        if (FALSE_WORDS.indexOf(s) > -1) { return false; }
    }
    return null;
};

self.hexToRgb = function(h) {
    if (typeof h !== 'string') { return null; }
    var s = h.trim().replace('#', '');
    if (/^[0-9a-fA-F]{3}$/.test(s)) { s = s.split('').map(function(c) { return c + c; }).join(''); }
    if (!/^[0-9a-fA-F]{6}$/.test(s)) { return null; }
    var n = parseInt(s, 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
};

// Icon ink for the orb. Measured on the rig: a white icon on the amber #f59e0b that the
// low-battery preset uses comes out at about 2:1, which is not readable. So pick the ink
// by WCAG contrast against the state colour rather than by a brightness guess, and take
// whichever of black and white actually wins.
self.wcagLum = function(c) {
    function lin(v) {
        v = v / 255;
        return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    }
    return 0.2126 * lin(c.r) + 0.7152 * lin(c.g) + 0.0722 * lin(c.b);
};
// A lamp glyph is a large graphical object, so 3:1 is the bar it has to clear (WCAG
// 1.4.11). White is preferred because that is what a lit lamp looks like; black is used
// only where white cannot reach 3:1 - measured, that is the bright ones such as #22c55e
// (2.3:1) and #f59e0b (2.1:1), while #ef4444 and #64748b keep the white glyph.
self.pickInk = function(color, bar) {
    var c = self.hexToRgb(color);
    if (!c) { return '#ffffff'; }
    var l = self.wcagLum(c);
    var onWhite = 1.05 / (l + 0.05);
    var onBlack = (l + 0.05) / 0.05;
    if (onWhite >= bar || onWhite >= onBlack) { return '#ffffff'; }
    return 'rgba(0, 0, 0, 0.82)';
};
// The glyph fills half the lamp, so it is a large graphical object and 3:1 is its bar.
self.orbInk = function(color) { return self.pickInk(color, 3); };
// The chip is 10px uppercase text on the same colour, which WCAG counts as normal text,
// so it owes 4.5. Measured, that is the difference between a white FAULT pill at 3.76:1
// and a dark one at 5.58:1, so picking the ink by contrast clears the pill too.
self.chipInk = function(color) { return self.pickInk(color, 4.5); };

// Ink from the first real backdrop above the widget rather than the platform theme, so a
// darkened card on a light dashboard still gets legible text.
self.resolveTheme = function(root) {
    var el = root, bg = null;
    while (el && el !== document.documentElement) {
        var c = window.getComputedStyle(el).backgroundColor;
        if (c && c !== 'transparent' && c.replace(/\s/g, '') !== 'rgba(0,0,0,0)') { bg = c; break; }
        el = el.parentElement;
    }
    var m = bg ? bg.match(/(\d+)[,\s]+(\d+)[,\s]+(\d+)/) : null;
    if (!m) { return; }
    var lum = 0.299 * +m[1] + 0.587 * +m[2] + 0.114 * +m[3];
    var dark = lum < 128;
    root.style.setProperty('--msl-ink', dark ? '#e7ecf3' : 'rgba(0, 0, 0, 0.85)');
    // #78849a is the house muted grey, but here it only ever carries the key name and
    // the age line - 10 to 12px bold uppercase, which WCAG counts as normal text, not
    // large. Measured at 3.77:1 on white, so the light side is one step darker to clear
    // 4.5. The dark side already measures 6.44:1 and is left alone.
    root.style.setProperty('--msl-muted', dark ? '#93a0b4' : '#697585');
    root.style.setProperty('--msl-line', dark ? '#333a45' : '#e2e7ef');
};

self.setVar = function(root, name, value) {
    if (value == null || value === '') { root.style.removeProperty(name); }
    else { root.style.setProperty(name, value); }
};

self.setFontVars = function(root, prefix, font) {
    if (!font || typeof font !== 'object') { return; }
    var base = '--msl-' + prefix + '-';
    if (font.size != null && font.size !== '') {
        self.setVar(root, base + 'size', String(font.size) + (font.sizeUnit || 'px'));
    }
    self.setVar(root, base + 'family', font.family);
    self.setVar(root, base + 'weight', font.weight != null ? String(font.weight) : null);
    self.setVar(root, base + 'style', font.style);
};

self.applyStyle = function() {
    var root = self.ctx.$container[0].querySelector('.msl');
    if (!root) { return; }
    self.resolveTheme(root);
    var s = self.ctx.settings || {};
    self.setFontVars(root, 'label', s.labelFont);
    self.setFontVars(root, 'key', s.keyFont);
    self.setFontVars(root, 'name', s.nameFont);
};

// ---- settings --------------------------------------------------------------

self.settings = function() {
    var s = self.ctx.settings || {};
    var rows = Array.isArray(s.states) ? s.states : [];
    var states = [];
    for (var i = 0; i < rows.length; i++) {
        var r = rows[i];
        if (!r || typeof r !== 'object') { continue; }
        var hasValue = r.value != null && String(r.value).trim() !== '';
        var min = self.num(r.min);
        var max = self.num(r.max);
        var hasBand = !hasValue && (min != null || max != null);
        if (!hasValue && !hasBand) { continue; }
        states.push({
            value: hasValue ? String(r.value).trim() : null,
            min: hasBand ? min : null,
            max: hasBand ? max : null,
            label: r.label != null && r.label !== '' ? String(r.label) : null,
            color: r.color || '#94a3b8',
            icon: r.icon || '',
            blink: r.blink === true
        });
    }
    return {
        states: states,
        fallbackLabel: s.fallbackLabel != null ? String(s.fallbackLabel) : '',
        fallbackColor: s.fallbackColor || '#94a3b8',
        fallbackIcon: s.fallbackIcon || '',
        square: s.shape === 'square',
        showIcon: s.showIcon !== false,
        showLabel: s.showLabel !== false,
        showKeyName: s.showKeyName !== false,
        glow: s.glow !== false,
        showChip: s.showVerdictChip !== false,
        showFoot: s.showFoot !== false,
        // Two fields, not one and an es/ies rule: `switch` -> `switchs` is the failure the
        // rule would ship, and it is one of the likelier words for a panel of lamps.
        unitOne: (s.unitNoun != null && String(s.unitNoun).trim() !== '')
            ? String(s.unitNoun).trim() : 'channel',
        unitMany: (s.unitNounPlural != null && String(s.unitNounPlural).trim() !== '')
            ? String(s.unitNounPlural).trim() : 'channels',
        staleMin: self.num(s.staleMinutes) || 0
    };
};

// ---- entities --------------------------------------------------------------

// Every cell carries its own `datasource` - confirmed on a live two-device dashboard, not assumed
// from the field name. `entityLabel` holds the device label when one is set and '' when not, so
// this is the same name ThingsBoard shows everywhere else.
self.entityOf = function(cell) {
    var ds = cell && cell.datasource;
    if (!ds) { return ''; }
    return (ds.entityLabel && String(ds.entityLabel).trim()) || ds.entityName || ds.name || '';
};

// What to call several of them in the head. Derived from `entityType` on the datasource rather
// than hardcoded, because a card watching assets should not say "devices".
var ENTITY_WORDS = {
    DEVICE: ['device', 'devices'],
    ASSET: ['asset', 'assets'],
    ENTITY_VIEW: ['entity view', 'entity views']
};
self.entityWord = function(types, n) {
    var pair = types.length === 1 ? ENTITY_WORDS[types[0]] : null;
    if (!pair) { pair = ['entity', 'entities']; }
    return n === 1 ? pair[0] : pair[1];
};

// ---- matching --------------------------------------------------------------

// First match wins, and the rows drag to reorder in the settings editor, so the
// operator controls precedence directly.
self.match = function(raw, st) {
    if (st.value != null) {
        if (raw != null && String(raw).trim().toLowerCase() === st.value.toLowerCase()) { return true; }
        var rn = self.num(raw), sn = self.num(st.value);
        if (rn != null && sn != null && rn === sn) { return true; }
        var rb = self.canonBool(raw), sb = self.canonBool(st.value);
        if (rb != null && sb != null && rb === sb) { return true; }
        return false;
    }
    var n = self.num(raw);
    if (n == null) { return false; }
    if (st.min != null && n < st.min) { return false; }
    if (st.max != null && n > st.max) { return false; }
    return true;
};

// Rows are already in priority order (first-match-wins, drag to reorder), so the card's
// verdict is just the lowest index any lamp matched - no second severity concept needed.
var NO_MATCH = 9999;

self.resolve = function(raw, cfg) {
    for (var i = 0; i < cfg.states.length; i++) {
        if (self.match(raw, cfg.states[i])) {
            var st = cfg.states[i];
            return {
                color: st.color,
                label: st.label != null ? st.label : String(raw),
                icon: st.icon,
                blink: st.blink,
                idx: i
            };
        }
    }
    return {
        color: cfg.fallbackColor,
        label: cfg.fallbackLabel !== '' ? cfg.fallbackLabel : String(raw),
        icon: cfg.fallbackIcon,
        blink: false,
        idx: NO_MATCH
    };
};

// ---- lifecycle -------------------------------------------------------------

self.onInit = function() {
    var scope = self.ctx.$scope;
    scope.state = 'loading';
    scope.lamps = [];
    scope.screen = null;
    scope.skeleton = [0, 1, 2];
    scope.sizeClass = 'md';
    scope.square = false;
    scope.showIcon = true;
    scope.showLabel = true;
    scope.showKeyName = true;
    scope.showHead = true;
    scope.showChip = true;
    scope.showFoot = true;
    scope.glow = true;
    scope.entityName = '';
    scope.verdict = null;
    scope.footItems = [];
    scope.freshness = '';
    self.render();
    if (typeof ResizeObserver !== 'undefined' && !self._ro) {
        self._ro = new ResizeObserver(function() { self.applySize(); });
        var el = self.ctx.$container[0].querySelector('.msl');
        if (el) { self._ro.observe(el); }
    }
    // Staleness is a function of the clock, not of an incoming packet, so a lamp that
    // stops reporting has to grey itself out without waiting for data that never comes.
    if (self._tick) { clearInterval(self._tick); }
    self._tick = setInterval(function() {
        if (self.ctx.$scope.state === 'ready') { self.render(); }
    }, 10000);
};

self.onDataUpdated = function() { self.render(); };
self.onResize = function() { self.applySize(); };

self.onDestroy = function() {
    if (self._ro) { self._ro.disconnect(); self._ro = null; }
    if (self._tick) { clearInterval(self._tick); self._tick = null; }
};

// Lamp size is chosen by whether the whole strip fits, not by width alone: walk the
// candidates largest-first, take the first whose wrapped grid is no taller than the card.
var GAP = { sm: 8, md: 12, lg: 14 };
var PADX = { sm: 10, md: 16, lg: 18 };      // left + right
var PADY = { sm: 16, md: 26, lg: 30 };      // top + bottom
var TEXTGAP = { sm: 6, md: 8, lg: 8 };
var KEYH = { sm: 13, md: 15, lg: 16 };
var LABELH = { sm: 15, md: 18, lg: 20 };
var MINW = { sm: 54, md: 76, lg: 88 };
var CANDIDATES = [['lg', 78], ['md', 62], ['md', 50], ['sm', 40], ['sm', 30], ['sm', 22]];

// Below the smallest lamp the text yields, not the lamp: the colour is the reading. The
// state label goes first (the colour already says it), then the key name; both stay in the
// tooltip and aria-label at every size, so nothing is lost.
// Every step, largest first: each lamp size in turn, then again with the label dropped,
// then again with the key name dropped too.
self.steps = function(cfg) {
    var out = [];
    // The head and the footer are what make this read as one of ours, so they are the
    // last thing given up - after the state label, then the key name.
    var modes = [
        { head: true, key: cfg.showKeyName, label: cfg.showLabel },
        { head: true, key: cfg.showKeyName, label: false },
        { head: true, key: false, label: false },
        { head: false, key: false, label: false }
    ];
    for (var m = 0; m < modes.length; m++) {
        for (var i = 0; i < CANDIDATES.length; i++) {
            out.push({
                cls: CANDIDATES[i][0], orb: CANDIDATES[i][1],
                head: modes[m].head, key: modes[m].key, label: modes[m].label
            });
        }
    }
    return out;
};

// FRAME is the vertical the head and footer take before the strip: 8px name row + 8 margin,
// and 6 pad + 1 rule + 13 text. FOOT is the footer's half, subtracted when it is off so the
// ladder does not reserve room for a row nothing draws.
var FRAME = 48;
var FOOT = 20;

self.firstFit = function(steps, w, h, n, frame) {
    for (var i = 0; i < steps.length; i++) {
        var s = steps[i], g = GAP[s.cls];
        var tw = Math.max(s.key || s.label ? MINW[s.cls] : 0, s.orb + PADX[s.cls]);
        var th = PADY[s.cls] + s.orb
            + (s.key ? KEYH[s.cls] + TEXTGAP[s.cls] : 0)
            + (s.label ? LABELH[s.cls] + TEXTGAP[s.cls] : 0);
        var cols = Math.max(1, Math.floor((w + g) / (tw + g)));
        var rows = Math.ceil(n / cols);
        var avail = h - (s.head ? frame : 0);
        if (rows * th + (rows - 1) * g <= avail) { return i; }
    }
    return steps.length - 1;
};

self.applyStep = function(el, scope, s) {
    el.style.setProperty('--msl-orb-size', s.orb + 'px');
    if (scope.sizeClass !== s.cls || scope.showKeyName !== s.key
            || scope.showLabel !== s.label || scope.showHead !== s.head) {
        scope.sizeClass = s.cls;
        scope.showKeyName = s.key;
        scope.showLabel = s.label;
        scope.showHead = s.head;
        self.ctx.detectChanges();
    }
};

// The box model above only chooses where to start; the rendered DOM decides whether it
// stays - step down until the strip genuinely stops scrolling.
self.applySize = function() {
    var el = self.ctx.$container[0].querySelector('.msl');
    if (!el) { return; }
    var scope = self.ctx.$scope;
    var n = Math.max(1, (scope.lamps || []).length);
    var steps = self.steps(self.settings());
    // The card's own padding is already outside clientWidth/Height of the strip, so the
    // model works from the card box minus the frame and the DOM corrects it from there.
    var box = el.getBoundingClientRect();
    var cs = window.getComputedStyle(el);
    var innerW = box.width - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
    var innerH = box.height - parseFloat(cs.paddingTop) - parseFloat(cs.paddingBottom);
    var cfg = self.settings();
    var i = self.firstFit(steps, innerW, innerH, n,
        FRAME - (cfg.showFoot ? 0 : FOOT));
    for (var guard = 0; guard < steps.length; guard++) {
        self.applyStep(el, scope, steps[i]);
        var strip = el.querySelector('.msl__strip');
        if (!strip) { return; }
        if (strip.scrollHeight <= strip.clientHeight + 1 || i >= steps.length - 1) { break; }
        i++;
    }
    self.fitFoot(el);
};

// Text width without laying anything out. A canvas 2D context measures a string in a
// given font synchronously, needs no element in the document and no change-detection pass,
// so the foot can be decided from the model alone.
self.textW = function(t, font) {
    if (!self._m) {
        var c = document.createElement('canvas');
        self._m = c.getContext ? c.getContext('2d') : null;
    }
    if (!self._m) { return t.length * 6; }
    self._m.font = font;
    return self._m.measureText(t).width;
};

// The foot decides which segments survive, worst-first, so that the ones that stay are
// whole rather than every segment rotting into an ellipsis at once. The age is not part of
// the calculation: it already yields first by its own flex-shrink, and an age stamp reading
// "13s" instead of "13s ago" costs the operator nothing.
//
// Deliberately a PURE FUNCTION of (segments, font, available width): it never reads what
// is currently rendered or mutates-then-re-measures, so its answer never depends on whether
// its own writes have landed (ctx.detectChanges swallows exceptions, so that is not assumable).
self.fitFoot = function(el) {
    var scope = self.ctx.$scope;
    var foot = el.querySelector('.msl__foot');
    var all = scope.footAll || [];
    if (!foot || !all.length) { return; }

    var cs = window.getComputedStyle(foot);
    var font = cs.fontStyle + ' ' + cs.fontWeight + ' ' + cs.fontSize + ' ' + cs.fontFamily;
    // Each segment after the first carries the flex gap plus the middot its ::before
    // draws, and that separator has its own margin. Read them rather than assume.
    var gap = parseFloat(cs.columnGap || cs.gap) || 0;
    // The separator ::before lives on the SECOND item (`.msl__foot-item + .msl__foot-item`),
    // so read a boundary from item two; item one returns content:none and a zero margin.
    var sep = gap;
    try {
        var second = foot.querySelectorAll('.msl__foot-item')[1];
        if (second) { sep = parseFloat(window.getComputedStyle(second, '::before').marginRight) || gap; }
    } catch (e) { sep = gap; }
    var boundary = gap + sep + self.textW('\u00b7', font);

    var avail = foot.clientWidth;
    if (!avail) { return; }

    // widest-first removal by priority: highest p goes first
    var order = all.slice().sort(function(a, b) { return b.p - a.p; });
    var keep = all.slice();
    for (var guard = 0; guard < all.length; guard++) {
        var need = 0;
        for (var i = 0; i < keep.length; i++) { need += self.textW(keep[i].t, font); }
        need += boundary * Math.max(0, keep.length - 1);
        // 2px of slack: sub-pixel text metrics against an integer clientWidth, and being
        // one pixel conservative costs a segment nobody would have read anyway.
        if (need <= avail - 2 || keep.length <= 1) { break; }
        var victim = null;
        for (var v = 0; v < order.length && victim === null; v++) {
            for (var w = 0; w < keep.length; w++) {
                if (keep[w] === order[v]) { victim = w; break; }
            }
        }
        if (victim === null) { break; }
        keep.splice(victim, 1);
    }

    var next = keep.map(function(f) { return f.t; });
    var cur = scope.footItems || [];
    var same = cur.length === next.length;
    for (var s = 0; same && s < next.length; s++) { if (cur[s] !== next[s]) { same = false; } }
    if (same) { return; }
    scope.footItems = next;
    self.ctx.detectChanges();
};

// ---- render ----------------------------------------------------------------

self.age = function(ms) {
    var sec = Math.floor(ms / 1000);
    if (sec < 60) { return sec + 's ago'; }
    var m = Math.floor(ms / 60000);
    if (m < 60) { return m + 'm ago'; }
    var h = Math.floor(m / 60);
    if (h < 24) { return h + 'h ago'; }
    return Math.floor(h / 24) + 'd ago';
};

// A list an operator can act on rather than a number they cannot. Three names is what fits the
// hint line on the smallest card; past that the count carries the rest.
self.nameList = function(items) {
    if (items.length <= 3) { return items.join(', '); }
    return items.slice(0, 3).join(', ') + ' and ' + (items.length - 3) + ' more';
};

self.render = function() {
    var scope = self.ctx.$scope;
    var cfg = self.settings();
    scope.square = cfg.square;
    scope.showIcon = cfg.showIcon;
    scope.showLabel = cfg.showLabel;
    scope.showKeyName = cfg.showKeyName;
    scope.glow = cfg.glow;

    var data = self.ctx.data || [];
    var lamps = [];
    var bad = [];
    var silent = [];
    var now = Date.now();

    // One pass to learn whether this card is watching one thing or several, because that is what
    // decides whether a lamp has to say which thing it is. Distinct NAMES, not datasource count:
    // two datasources pointed at the same entity are one thing to the operator reading the card.
    var names = {}, types = {}, keyset = {}, nEntities = 0, nKeys = 0;
    for (var e = 0; e < data.length; e++) {
        var en = self.entityOf(data[e]);
        if (en && !names[en]) { names[en] = true; nEntities++; }
        var et = data[e].datasource && data[e].datasource.entityType;
        if (et) { types[et] = true; }
        var kn = (data[e].dataKey && (data[e].dataKey.label || data[e].dataKey.name)) || '';
        if (kn && !keyset[kn]) { keyset[kn] = true; nKeys++; }
    }
    var multi = nEntities > 1;
    var typeList = Object.keys(types);
    // When every lamp carries the same key, that key is the one word on the caption that tells
    // nothing apart. Measured at five devices on an 8x4 card: `LINE 1 - AC...` truncates and loses
    // the key anyway, while the entity alone fits. So the caption drops the key exactly when it is
    // the same everywhere, and the tooltip and the aria-label keep both in every case.
    var sameKey = multi && nKeys === 1;

    for (var i = 0; i < data.length; i++) {
        var cell = data[i];
        var pts = cell.data || [];
        var key = (cell.dataKey && (cell.dataKey.label || cell.dataKey.name)) || '';
        // Under several entities a bare key name is ambiguous - three devices all publishing
        // `active` produce three identical captions - so the name of the thing goes in front of it.
        var ent = multi ? self.entityOf(cell) : '';
        var caption = (ent && sameKey) ? ent
            : (ent ? (ent + ' \u00b7 ' + (key || ('key ' + (i + 1)))) : key);
        var who = ent ? (ent + ' \u00b7 ' + (key || ('key ' + (i + 1)))) : key;
        if (!pts.length) { silent.push(who || ('key ' + (i + 1))); continue; }
        var last = pts[pts.length - 1];
        var ts = last[0];
        var raw = last[1];

        // A key that is bound but never published still arrives as a datapoint carrying an
        // empty string, so "pts.length" alone is not the test for having a reading.
        if (raw == null || (typeof raw === 'string' && raw.trim() === '')) {
            silent.push(who || ('key ' + (i + 1)));
            continue;
        }

        // A lamp is one value; an object or array cannot be, so it gets its own screen rather
        // than a misleading "no data". TB returns JSON telemetry as a string, so the string
        // form is the one that fires; the typeof test stays for the day that changes.
        var isObj = (typeof raw === 'object')
            || (typeof raw === 'string' && /^[[{]/.test(raw.trim()));
        if (isObj) { bad.push(who || ('key ' + (i + 1))); continue; }

        var st = self.resolve(raw, cfg);
        var stale = cfg.staleMin > 0 && ts != null && (now - ts) > cfg.staleMin * 60000;
        // Always carried, even when the size class hides it: the tooltip and the
        // aria-label read it, and applySize can turn the caption back on on resize
        // without another data round.
        var label = st.label;
        // The shipped pattern is `key, state, stale`; with several entities it becomes
        // `entity, key, state, stale`. One pattern extended, not a second one invented.
        var aria = (ent ? ent + ', ' : '') + (key ? key + ', ' : '')
            + st.label + (stale ? ', stale' : '');
        var tip = (who ? who + ': ' : '') + String(raw)
            + (stale && ts != null ? '  (' + self.age(now - ts) + ')' : '');
        lamps.push({
            key: caption,
            entity: ent,
            label: label,
            color: st.color,
            ink: self.orbInk(st.color),
            icon: st.icon,
            blink: st.blink && !stale,
            stale: stale,
            idx: st.idx,
            ts: ts,
            aria: aria,
            tip: tip
        });
    }

    if (!lamps.length) {
        // "keys bound, device has never reported" and "nothing bound at all" are
        // different problems, so they get separate screens.
        if (bad.length) {
            scope.screen = {
                bad: true,
                icon: 'error_outline',
                title: 'Cannot light this value',
                hint: bad.length === 1
                    ? ('"' + bad[0] + '" holds an object, not a single value')
                    : (self.nameList(bad) + ' hold objects, not single values')
            };
        } else if (silent.length) {
            scope.screen = {
                bad: false,
                icon: 'hourglass_empty',
                title: 'Waiting for data',
                hint: silent.length === 1
                    ? ('"' + silent[0] + '" is bound but has not reported yet')
                    : (self.nameList(silent) + ' have not reported yet')
            };
        } else {
            scope.screen = {
                bad: false,
                icon: 'lightbulb_outline',
                title: 'No data',
                hint: 'Bind a boolean, string or numeric key'
            };
        }
        scope.state = 'empty';
        self.ctx.detectChanges();
        return;
    }

    // With one entity the head names it, which is the common case and is unchanged. With several
    // it must not name the first one and pretend to speak for the rest, so it says how many things
    // are on the card instead - and each lamp carries its own name.
    if (multi) {
        scope.entityName = nEntities + ' ' + self.entityWord(typeList, nEntities);
    } else {
        var one = data.length ? self.entityOf(data[0]) : '';
        var ds = self.ctx.datasources && self.ctx.datasources[0];
        scope.entityName = one || (ds && ds.entityName) || '';
    }

    // The verdict is the highest-priority state present, and priority is row order, which
    // the operator set by dragging. No separate severity scale to keep in sync.
    var best = null, hits = 0, staleCount = 0, newest = null;
    for (var k = 0; k < lamps.length; k++) {
        var L = lamps[k];
        if (best === null || L.idx < best.idx) { best = L; }
        if (L.stale) { staleCount++; }
        if (L.ts != null && (newest === null || L.ts > newest)) { newest = L.ts; }
    }
    for (var k2 = 0; k2 < lamps.length; k2++) {
        if (lamps[k2].idx === best.idx) { hits++; }
    }
    // A card where nothing matched a row shows no chip unless the operator wrote a label
    // for that case - an empty pill would be a claim with no content.
    scope.verdict = (best.idx === NO_MATCH && cfg.fallbackLabel === '')
        ? null
        : { label: best.label, color: best.color, ink: self.chipInk(best.color) };

    // Each segment carries how hard it is to give up (lower = kept longer): below ~155px
    // the row cannot hold all three. The state count yields first - the verdict chip
    // already says which state it is.
    var foot = [];
    foot.push({ t: lamps.length + ' '
        + (lamps.length === 1 ? cfg.unitOne : cfg.unitMany), p: 0 });
    if (lamps.length > 1 && scope.verdict && hits < lamps.length) {
        foot.push({ t: hits + ' ' + best.label, p: 2 });
    }
    if (staleCount) { foot.push({ t: staleCount + ' stale', p: 1 }); }
    scope.footAll = foot;
    // Always the full list here. applySize re-derives from footAll on every resize, so
    // this is the model and the rendered list is only ever its output.
    scope.footItems = foot.map(function(f) { return f.t; });
    scope.freshness = newest != null ? self.age(now - newest) : '';
    scope.showChip = cfg.showChip;
    scope.showFoot = cfg.showFoot;

    scope.screen = null;
    scope.lamps = lamps;
    scope.state = 'ready';
    self.ctx.detectChanges();
    self.applyStyle();
    self.applySize();
};
